     * @example
     * ```tsx
     * const { isReady, invoke, resourceUrl } = useSPFxAadHttpClient('https://api.contoso.com');
     *
     * if (!isReady) return <Spinner />;
     *
     * // Safe to use client or invoke
     * const data = await invoke(c => c.get(`${resourceUrl}/api/data`, ...).then(r => r.json()));
     * ```
     */
